 if(b.type==='farm'){ctx.fillStyle='#b4ab65';ctx.fillRect(x-26,y+7,52,20);ctx.strokeStyle='#837f4b';ctx.lineWidth=1;for(let j=0;j<5;j++){ctx.beginPath();ctx.moveTo(x-26,y+9+j*4);ctx.lineTo(x+26,y+9+j*4);ctx.stroke();}}
