 const seg=[];for(const [k,type]of Object.entries(game.s.roads)){const [x,y]=k.split(',').map(Number);if(x<x0-1||x>x1+1||y<y0-1||y>y1+1)continue;for(const [dx,dy]of [[1,0],[0,1]])if(game.s.roads[key(x+dx,y+dy)])seg.push([x,y,dx,dy,type]);}
 for(let pass=0;pass<2;pass++)for(const [x,y,dx,dy,type]of seg){ctx.lineCap='round';ctx.strokeStyle=pass===0?'#536d4e':type==='main'?'#c9bb8c':'#c2ae7e';ctx.lineWidth=pass===0?(type==='main'?13:9):(type==='main'?9:6);ctx.beginPath();ctx.moveTo(x*32,y*32);ctx.lineTo((x+dx)*32,(y+dy)*32);ctx.stroke();}
 for(const b of game.s.buildings)for(const [dx,dy]of [[1,0],[0,1],[-1,0],[0,-1]])if(game.s.roads[key(b.x+dx,b.y+dy)]){ctx.lineWidth=6;ctx.strokeStyle='#c8b68a';ctx.beginPath();ctx.moveTo(b.x*32,b.y*32);ctx.lineTo((b.x+dx)*32,(b.y+dy)*32);ctx.stroke();}
 ctx.setLineDash([7,8]);for(const s of game.s.sectors){ctx.strokeStyle=s.owner===0?'#a8d5c19a':s.owner===1?'#e1a18d8a':'#e9deab4d';ctx.lineWidth=2/cam.zoom;ctx.strokeRect(s.sx*32-15,s.sy*32-15,640,576);}ctx.setLineDash([]);
 if(showRoutes)for(const a of game.s.agents.filter(a=>a.owner===0&&a.job)){ctx.strokeStyle=a.role==='carrier'?'#f2d78dc0':'#aed9e48f';ctx.lineWidth=1.5/cam.zoom;ctx.beginPath();const p=game.pos(a);ctx.moveTo(p[0]*32,p[1]*32);for(const n of a.route)ctx.lineTo(n[0]*32,n[1]*32);ctx.stroke();}
