 if(action==='supply')command('supplyRule',{from:$('supplyFrom').value,to:$('supplyTo').value,resource:opsResource,target:Number($('supplyTarget').value),reserve:Number($('supplyReserve').value),priority:Number($('supplyPriority').value)});
