function panKeys(dt){
 if(!started||!$('welcome').hidden||['INPUT','SELECT','TEXTAREA'].includes(document.activeElement?.tagName))return;
 const x=(pressedKeys.has('KeyD')||pressedKeys.has('ArrowRight')?1:0)-(pressedKeys.has('KeyA')||pressedKeys.has('ArrowLeft')?1:0),y=(pressedKeys.has('KeyS')||pressedKeys.has('ArrowDown')?1:0)-(pressedKeys.has('KeyW')||pressedKeys.has('ArrowUp')?1:0);
 if(x||y){const norm=Math.hypot(x,y);cam.x+=x/norm*420*dt/cam.zoom;cam.y+=y/norm*420*dt/cam.zoom;}
}

